Q: Avoid synthetic sounds overlapping A: <p>Make the <code>oscillator</code> and <code>gainNode</code> outside of the function, and change the frequency inside the function.</p>
<p><code>btn5</code> allows you to temporarily stop the sound by setting the frequency to zero.</p>
<pre><code>&lt;body&gt;

&lt;div id = &quot;button-container&quot; class=&quot;synth&quot;&gt;
&lt;button class = &quot;note&quot; id = &quot;btn1&quot;&gt;1&lt;/button&gt;
&lt;button class = &quot;note&quot; id = &quot;btn2&quot;&gt;2&lt;/button&gt;
&lt;button class = &quot;note&quot; id = &quot;btn3&quot;&gt;3&lt;/button&gt;
&lt;button class = &quot;note&quot; id = &quot;btn4&quot;&gt;4&lt;/button&gt;
&lt;button class = &quot;note&quot; id = &quot;btn5&quot;&gt;5&lt;/button&gt;
&lt;/div&gt;

&lt;script&gt;

const audioCtx = new AudioContext();
const oscillator = audioCtx.createOscillator();  
oscillator.type = 'triangle'; 
oscillator.frequency.setValueAtTime(0,0)  
const gainNode = audioCtx.createGain();
oscillator.connect(gainNode);
gainNode.connect(audioCtx.destination);                     
oscillator.start();   

document.addEventListener('click', function(evt) {

let Key = evt.target.id;

if(Key == &quot;btn1&quot;) frq = 200;
if(Key == &quot;btn2&quot;) frq = 300;
if(Key == &quot;btn3&quot;) frq = 400;
if(Key == &quot;btn4&quot;) frq = 500;
if(Key == &quot;btn5&quot;) frq = 0;

oscillator.frequency.setValueAtTime(frq,0);

});

&lt;/script&gt;

&lt;/body&gt;
</code></pre>
